// Pure checks behind `npm run check:repo`, kept apart from the git and file I/O so tests can
// exercise them directly.

/** The most the tracked files may weigh in total: 10 MiB. */
export const MAX_TOTAL_BYTES = 10 * 1024 * 1024;

// Built from code points so this file does not itself contain the characters it forbids.
const EM_DASH = String.fromCodePoint(0x2014);
const EN_DASH = String.fromCodePoint(0x2013);

// Generated by npm, not written by hand.
const DASH_CHECK_EXEMPT = new Set(['package-lock.json']);

/** One em-dash or en-dash found in a tracked file, with its path and 1-based line number. */
export interface DashFinding {
  readonly path: string;
  readonly line: number;
  readonly dash: 'em-dash' | 'en-dash';
}

/** The tracked paths that belong to the private planning folder, which must never be committed. */
export function findPlanningPaths(paths: readonly string[]): string[] {
  return paths.filter((path) => path === '.planning' || path.startsWith('.planning/'));
}

/**
 * Lists every line of `text` that holds an em-dash or an en-dash, one finding per kind per line.
 * Returns nothing for the exempt files.
 */
export function findDashes(path: string, text: string): DashFinding[] {
  if (DASH_CHECK_EXEMPT.has(path)) return [];
  const findings: DashFinding[] = [];
  text.split('\n').forEach((content, index) => {
    if (content.includes(EM_DASH)) findings.push({ path, line: index + 1, dash: 'em-dash' });
    if (content.includes(EN_DASH)) findings.push({ path, line: index + 1, dash: 'en-dash' });
  });
  return findings;
}

/** A file is binary when its first 8000 bytes contain a NUL; text checks skip those. */
export function isBinary(bytes: Uint8Array): boolean {
  return bytes.subarray(0, 8000).includes(0);
}

/** The number of lines in `text`; a final newline does not start another line, and "" is 0. */
export function countLines(text: string): number {
  if (text === '') return 0;
  return text.endsWith('\n') ? text.split('\n').length - 1 : text.split('\n').length;
}

/** The group a tracked file is counted in for the size report. */
export type Bucket = 'src' | 'src/data' | 'tests' | 'tests/fixtures' | 'other';

/** Code and data are reported separately so a large recorded fixture is not read as source. */
export function bucketOf(path: string): Bucket {
  // The longer prefixes come first: src/data/ is inside src/, and tests/fixtures/ inside tests/.
  if (path.startsWith('src/data/')) return 'src/data';
  if (path.startsWith('src/')) return 'src';
  if (path.startsWith('tests/fixtures/')) return 'tests/fixtures';
  if (path.startsWith('tests/')) return 'tests';
  return 'other';
}

/** The totals the size report prints: files, bytes, and lines per bucket (not "other"). */
export interface SizeReport {
  readonly files: number;
  readonly bytes: number;
  readonly lines: Readonly<Record<Exclude<Bucket, 'other'>, number>>;
}

/** The size report as printed lines: file count, size against the limit, and lines per bucket. */
export function formatReport(report: SizeReport): string {
  // Sizes are shown in MiB (1024 x 1024 bytes) with two decimals.
  const megabytes = (report.bytes / (1024 * 1024)).toFixed(2);
  return [
    `Tracked files: ${String(report.files)}`,
    `Total size: ${megabytes} MB (limit ${String(MAX_TOTAL_BYTES / (1024 * 1024))} MB)`,
    `Lines in src (without src/data): ${String(report.lines.src)}`,
    `Lines in src/data: ${String(report.lines['src/data'])}`,
    `Lines in tests (without fixtures): ${String(report.lines.tests)}`,
    `Lines in tests/fixtures: ${String(report.lines['tests/fixtures'])}`,
  ].join('\n');
}
